// Stable edge references define local fold bands. No template names or global silhouette band.
export function fallRegions(o,m){if(!m.edgeIds?.length)return [];const ns=o.nodes,area=ns.reduce((v,a,i)=>{const b=ns[(i+1)%ns.length];return v+a.x*b.y-b.x*a.y;},0),sign=o.closed?(Math.sign(area)||1):1,flags=ns.map(a=>m.edgeIds.includes(a.edgeId)||a.edgeParents?.some(id=>m.edgeIds.includes(id))),count=ns.length-(o.closed?0:1),start=o.closed?(flags.findIndex(f=>!f)+1)%ns.length:0,runs=[];let run=null;for(let j=0;j<count;j++){const i=(start+j)%ns.length;if(flags[i]){if(!run)run={a:ns[i]};run.b=ns[(i+1)%ns.length];}else if(run){runs.push(run);run=null;}}if(run)runs.push(run);return runs.flatMap(({a,b})=>{const size=Math.hypot(b.x-a.x,b.y-a.y);if(size<.01)return [];const tx=(b.x-a.x)/size,ty=(b.y-a.y)/size,matrix=o.matrix||[1,0,0,1,0,0],cx=(a.x+b.x)/2,cy=(a.y+b.y)/2,worldX=matrix[0]*cx+matrix[2]*cy+matrix[4],worldTangent=matrix[0]*tx+matrix[2]*ty,parity=m.symmetryScope?(Math.sign(worldX-m.symmetryScope.axis)||1)*(Math.sign(worldTangent)||1):1;return [{a,b,size,tx,ty,nx:-ty*sign,ny:tx*sign,extent:Math.max(1,m.length??70),parity}];});}
export function fallWarp(p,regions,m){let dx=0,dy=0;for(const r of regions){const x=p.x-r.a.x,y=p.y-r.a.y,u=x*r.tx+y*r.ty,v=x*r.nx+y*r.ny,t=v/r.extent,pad=Math.min(16,r.size*.15);if(t<0||t>1||u<-pad||u>r.size+pad)continue;const fade=u<0?1+u/pad:u>r.size?1-(u-r.size)/pad:1,wave=Math.sin(Math.PI*t)*Math.sin(t*Math.max(1,m.foldCount??3)*Math.PI*2),noise=(m.irregularity??.3)*Math.sin(Math.PI*t)*Math.sin(t*17+(m.seed??1)),amount=Math.min(25,Math.max(0,m.intensity??5))*(wave+noise)*fade*r.parity;dx+=r.tx*amount;dy+=r.ty*amount;}return {...p,x:p.x+dx,y:p.y+dy};}
export function fallFoldLines(regions,m){const lines=[],count=Math.max(0,Math.min(12,Math.round(m.foldCount??3)));for(const r of regions)for(let i=1;i<=count;i++){const v=r.extent*i/(count+1),line=[];for(let j=0;j<=12;j++){const u=r.size*j/12,curve=Math.sin((r.parity<0?1-j/12:j/12)*Math.PI*2+i)*(m.intensity??5)*.3,linePoint={x:r.a.x+r.tx*u+r.nx*(v+curve),y:r.a.y+r.ty*u+r.ny*(v+curve)};line.push(fallWarp(linePoint,[r],m));}lines.push(line);}return lines;}
